// ExecutionReportBuilder builds a ExecutionReport message. A copy shares its fields and
// groups with the original.
type ExecutionReportBuilder struct {
	*fix.Builder
	groups *executionReport_groups
}

func BuildExecutionReport(beginString string) *ExecutionReportBuilder {
	b := &ExecutionReportBuilder{
		Builder: fix.NewBuilder(beginString, "8"),
		groups:  &executionReport_groups{},
	}
	b.SetSections(standardHeader, standardTrailer, nil)
	b.SetGroups(b.groups.appendTo, TagNoPartyIDs, TagNoContraBrokers, TagNoAllocs, TagNoSecurityAltID, TagNoEvents, TagNoInstrumentParties, TagNoContractualDefinitions, TagNoFinancingTermSupplements, TagNoContractualMatrices, TagNoStipulations, TagNoStrategyParameters, TagNoFills, TagNoContAmts, TagNoMiscFees, TagNoTrdRegTimestamps, TagNoRateSources, TagNoMatchInst, TagNoLimitAmts, TagNoTargetPartyIDs, TagNoOrderEvents, TagNoDisclosureInstructions, TagNoRegulatoryTradeIDs, TagNoRelativeValues, TagNoCommissions, TagNoOrderAttributes, TagNoTrdRegPublications, TagNoTradePriceConditions, TagNoValueChecks, TagNoPayments, TagNoPriceQualifiers, TagNoOrders)
	b.OnReset(b.groups.reset)
	return b
}
